const greeting = "Hello";

function greet(name) {
  return `${greeting}, ${name}`;
}

function welcome() {
  const greeting = "Welcome";

  return greet("Ada");
}

function goodbye() {
  const greeting = "Bye";
  const greet = (name) => `${greeting}, ${name}`;

  return greet("Lin");
}

console.log(welcome());
console.log(goodbye());
